INSERT INTO `admission_item_sections` (`id`, `admission_item_id`, `images`, `description`, `created_at`, `updated_at`) VALUES
(2, 2, '[\"uploads/admission_item_sections/805d75d0-84ff-408b-a5f3-339362bc8e8a.jpg\"]', '<p><b>Admission support refers to professional guidance and assistance throughout the university application process, from course selection to receiving the official offer letter.</b><br><br>Our admission support service is designed to:&nbsp; &nbsp; &nbsp;<br>• Match students with approved and suitable universities<br>• Maximize offer letter success<br>• Reduce application errors and rejections<br>• Save time, cost, and stress for students and parents</p>', '2025-12-18 00:15:22', '2026-01-15 05:46:41');
INSERT INTO `admission_item_sections` (`id`, `admission_item_id`, `images`, `description`, `created_at`, `updated_at`) VALUES
(3, 3, '[]', '<p>At Insaf Immigration, our admission support covers every essential step:</p><p>Academic Profile Assessment<br>&nbsp; &nbsp; </p><p>We carefully evaluate:<br>• Academic background<br>• Study gap<br>• English proficiency<br>• Financial capability<br>• Career goals<br>This ensures students apply to realistic and visa-friendly institutions.<br></p><p><br>University &amp; Course Selection</p><p>We help students choose:<br>• Government-approved universities<br>• Career-oriented and job-demand courses<br>• Budget-friendly institutions<br>• High visa success destinations<br>Our goal is long-term success, not random admissions.</p><p><img style=\"width: 1326.83px;\" src=\"data:image/jpeg;base64,\" data-filename=\"Subject selection image.jpg\"><br></p><p><br></p>', '2026-01-15 04:05:53', '2026-01-15 04:19:39');
INSERT INTO `admission_item_sections` (`id`, `admission_item_id`, `images`, `description`, `created_at`, `updated_at`) VALUES
(4, 4, '[]', '<p>Our expert team handles:<br>• Online application forms<br>• Document verification<br>• Statement of Purpose (SOP) guidance<br>• Academic document formatting<br>We ensure 100% accurate and error-free submissions.<br><br>Offer Letter &amp; Conditional Offer Guidance<br>We assist students with:<br>• Offer letter review and explanation<br>• Meeting conditions (if any)<br>• Course or university change if required<br>Students clearly understand what they are accepting and why.<br>&nbsp;&nbsp;&nbsp;&nbsp;<br>Countries We Support for Admission<br>Through our admission support service, we assist students applying to:<br>• Australia<br>• United Kingdom<br>• Canada<br>• USA<br>• Europe (Malta, Cyprus, Lithuania, etc.)<br>• Malaysia<br>• South Korea<br>• Japan<br>• Russia</p>', '2026-01-15 04:13:50', '2026-01-15 04:13:50'),
(5, 5, '[]', '<p>Our admission support is ideal for:</p><p>• SSC / HSC / A-Level / O-Level students<br>• Diploma &amp; Bachelor graduates<br>• Master’s applicants<br>• Students with study gap<br>• Students applying with or without IELTS<br>We offer customized admission strategies, not one-size-fits-all solutions.</p>', '2026-01-15 04:15:41', '2026-01-15 04:15:41'),
(6, 6, '[]', '<p>Many students face rejection due to:<br>• Wrong course selection<br>• Incomplete or incorrect documents<br>• Poor academic matching<br>• Applying to non-visa-friendly institutions<br><br>With Insaf Immigration’s admission support, students benefit from:<br>• Higher admission success rate<br>• Reduced rejection risk<br>• Faster offer letter processing<br>• Clear academic and career direction</p>', '2026-01-15 04:16:19', '2026-01-15 04:16:19'),
(7, 7, '[]', '<p>As a leading student visa and education consultancy in Bangladesh,&nbsp;<br>Insaf Immigration stands out because of:<br>• Experienced education counselors<br>• Strong university partnerships<br>• Country-specific admission expertise<br>• Non-IELTS and alternative pathway options<br>• Transparent and honest guidance<br>• Proven student success record<br>We prioritize student future over short-term sales.</p>', '2026-01-15 04:17:27', '2026-01-15 04:17:27'),
(8, 8, '[]', '<p>Admission and visa approval go hand in hand.<br><br>Our team ensures:<br>• Course selection aligns with visa requirements<br>• Financial planning meets embassy standards<br>• Academic logic supports visa approval<br>This integrated approach significantly increases student visa success rate</p>', '2026-01-15 04:18:13', '2026-01-15 04:18:13'),
(9, 9, '[]', '<p>If you are planning to study abroad from Bangladesh, professional admission support is the first step toward success. With Insaf Immigration, you receive expert guidance, real universities, and genuine career pathways.<br><br>Contact Insaf Immigration today for admission counseling and take the first step toward your international education journey.</p>', '2026-01-15 04:18:59', '2026-01-15 04:18:59');

