CREATE TABLE `destination_item_sections` (
  `id` bigint UNSIGNED NOT NULL,
  `destination_item_id` bigint UNSIGNED NOT NULL,
  `images` json DEFAULT NULL,
  `description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `destination_item_sections`
--

INSERT INTO `destination_item_sections` (`id`, `destination_item_id`, `images`, `description`, `created_at`, `updated_at`) VALUES
(7, 9, '[\"uploads/destination_item_sections/a6d01d85-541a-4fd5-a6b2-f03667b528fa.jpg\"]', 'Australia consistently ranks among the top study abroad destinations for international<br>students. Here’s why Bangladeshi students choose Australia:<br>• Globally recognized universities and qualifications<br>• High-quality education with practical learning<br>• Part-time work opportunities during study<br>• Attractive post-study work rights<br>• Safe, student-friendly, and multicultural society<br>• Strong Bangladeshi student community<br>Australian degrees are accepted worldwide, making graduates highly employable both<br>internationally and in Bangladesh.', '2025-12-16 23:34:37', '2026-01-14 06:28:57'),
(8, 11, '[]', '<div class=\"elementor-element elementor-element-ddc01ea elementor-widget elementor-widget-text-editor\" data-id=\"ddc01ea\" data-element_type=\"widget\" data-widget_type=\"text-editor.default\"><div class=\"elementor-widget-container\"><p><span style=\"font-weight: 400;\">Bangladeshi students can choose from a wide range of in-demand programs, including:<br>• Business &amp; Management<br>• Information Technology (IT)<br>• Engineering<br>• Health Sciences &amp; Nursing<br>• Hospitality &amp; Tourism Management<br>• Accounting &amp; Finance<br>• Data Science &amp; Artificial Intelligence</span></p><p><span style=\"font-weight: 400;\"><br>Our expert counselors at <b>Insaf Immigration</b> help you select the right course and university<br>based on your academic background, career goals, and budget.<br><br><br></span></p>								</div>\r\n				</div><p><br></p>', '2025-12-17 04:28:24', '2026-01-14 06:30:05'),
(10, 13, '[]', '<p>To apply for an Australia student visa (Subclass 500), students generally need:<br>• Valid passport</p><p>• Offer letter from an Australian institution<br>• Academic certificates and transcripts<br>• Proof of financial capacity<br>• English proficiency (IELTS / alternative options)<br>• Genuine Student (GS) statement<br>• Health and character documents<br></p><p><br>A small mistake can cause visa rejection. That’s why choosing a trusted student visa agency inBangladesh is critical.</p>', '2026-01-14 06:32:30', '2026-01-14 06:32:30'),
(11, 14, '[]', '<p>Most Australian institutions require IELTS, but scores may vary depending on the course and<br>university.<br>Typical requirement:<br>• IELTS overall 6.0 – 6.5<br>Our counselors guide you on IELTS preparation, waivers (if applicable), and alternative<br>pathways to maximize your visa success.</p>', '2026-01-14 06:33:16', '2026-01-14 06:33:16'),
(12, 15, '[]', '<p>The cost depends on the course, university, and city.<br>Approximate costs:<br>• Tuition fees: AUD 18,000 – 35,000 per year<br>• Living cost: AUD 21,000 per year (as per visa guidelines)<br>At <span style=\"font-weight: normal;\">Insaf Immigration</span>, we help students find budget-friendly universities, scholarships, and smart financial planning options.</p>', '2026-01-14 06:34:13', '2026-01-14 06:34:13'),
(13, 16, '[]', '<p>Australia allows international students to work part-time during study and full-time during<br>holidays.<br>Benefits include:<br>• Earning while studying<br>• Gaining local work experience<br>• Supporting living expenses</p><p>After graduation, eligible students can apply for post-study work visas, making Australia an excellent long-term career destination.</p>', '2026-01-14 06:35:20', '2026-01-14 06:35:20'),
(14, 17, '[]', '<p>Insaf Immigration is a trusted student visa consultancy in Bangladesh with a strong focus on<br>Australia.<br>We offer:<br>• Honest and professional counseling<br>• University and course selection support<br>• Strong visa documentation &amp; GS statement preparation<br>• High student visa success rate<br>• Transparent process with no hidden costs<br>• Pre-departure briefing, air ticket, and airport pickup support<br>We don’t give false promises — we deliver results</p>', '2026-01-14 06:36:27', '2026-01-14 06:36:27'),
(15, 18, '[]', '<p>If you are planning to study in Australia from Bangladesh, now is the right time to take action.With proper guidance and expert support, your Australian education dream is achievable.<br></p><p><br>Contact <span style=\"font-weight: normal;\">Insaf Immigration</span> today for a free consultation and take the first step toward your global future.</p>', '2026-01-14 06:37:20', '2026-01-14 06:37:20'),
(16, 19, '[]', '<p>The United Kingdom is one of the most prestigious and trusted study destinations for Bangladeshi students. With world-renowned universities, shorter course durations, globally<br>recognized degrees, and strong post-study work opportunities, studying in the UK offers exceptional value and career growth.<br></p><p><br>At Insaf Immigration, we provide complete support for UK student visas from Bangladesh, ensuring a smooth, transparent, and successful application process.</p>', '2026-01-14 06:42:58', '2026-01-14 06:42:58'),
(17, 10, '[]', '<p>The UK has been a top choice for international students for decades. Bangladeshi students<br>choose the UK because of:<br>• World-class universities with global rankings<br>• Shorter course duration (save time &amp; cost)<br>• One-year Master’s programs<br>• Strong Graduate Route (Post-Study Work)<br>• High academic standards and quality education<br>• Multicultural and student-friendly environment<br>A UK degree significantly increases global employability.</p>', '2026-01-14 06:43:50', '2026-01-14 06:43:50'),
(18, 20, '[]', '<p>UK universities offer a wide range of career-focused programs, including:<br>• Business &amp; Management<br>• Accounting &amp; Finance<br>• Computer Science &amp; IT<br>• Engineering<br>• Law<br>• Health &amp; Public Health• Data Science &amp; Artificial Intelligence<br>Insaf Immigration helps students choose the right course and university based on academic<br>profile, budget, and future career goals.</p>', '2026-01-14 06:44:37', '2026-01-14 06:44:37'),
(19, 21, '[]', '<p>To apply for a UK Student Visa, students typically need:<br>• Valid passport<br>• CAS (Confirmation of Acceptance for Studies)<br>• Academic certificates and transcripts<br>• Proof of funds (bank statement)<br>• English language proficiency (IELTS or alternatives)<br>• Tuberculosis (TB) test report<br>Our experienced visa team ensures 100% accurate documentation, reducing the risk of refusal.</p>', '2026-01-14 06:45:44', '2026-01-14 06:45:44'),
(20, 22, '[]', '<p>Most UK universities require IELTS, but score requirements vary.<br>Typical IELTS requirement:<br>• IELTS 6.0 – 6.5 overall<br>Some universities accept IELTS waiver or alternative tests depending on academic<br>background. Our counselors will guide you with the best option.</p>', '2026-01-14 06:46:38', '2026-01-14 06:46:38'),
(21, 23, '[]', '<p>The UK offers excellent value due to shorter course duration.<br>Estimated costs:<br>• Tuition fees: GBP 10,000 – 18,000 per year<br>• Living cost: GBP 9,000 – 12,000 per year<br>At <span style=\"font-weight: normal;\">Insaf Immigration</span>, we help students find affordable UK universities, scholarships, and smart<br>financial planning options.</p>', '2026-01-14 06:49:09', '2026-01-14 06:49:09'),
(22, 24, '[]', '<p>International students in the UK can work</p><p>• 20 hours per week during term time<br>• Full-time during holidays<br>After graduation, students can apply for the UK Graduate Route, allowing them to work in the<br>UK for up to 2 years (3 years for PhD).</p>', '2026-01-14 06:50:08', '2026-01-14 06:50:08'),
(23, 25, '[]', '<p>Insaf Immigration is a trusted student visa agency in Bangladesh, specializing in UK education.<br>We provide:<br>• Honest and expert counseling<br>• University &amp; course selection assistance<br>• Strong SOP and visa file preparation<br>• High UK student visa success rate<br>• Transparent pricing with no hidden costs<br>• Pre-departure briefing, air ticket, and airport pickup support<br>We guide students with integrity and results — not false promises.</p>', '2026-01-14 06:51:00', '2026-01-14 06:51:00'),
(24, 26, '[]', '<p>If you are planning to study in the UK from Bangladesh, now is the right time to apply. With expert guidance and proper planning, your UK education dream is fully achievable.<br>Contact Insaf Immigration today for a free consultation and secure your future in the UK.</p>', '2026-01-14 06:51:56', '2026-01-14 06:51:56'),
(25, 27, '[]', '<p>Canada is one of the most preferred study destinations for Bangladeshi students due to its world-class education system, affordable tuition options, excellent work opportunities, and<br>strong pathways to permanent residency. With globally recognized degrees and a high quality of life, studying in Canada is a smart long-term investment for your future.<br></p><p><br>At Insaf Immigration, we provide complete and professional support for Canada student visas from Bangladesh, ensuring accuracy, transparency, and high success rates.</p>', '2026-01-14 07:15:28', '2026-01-14 07:15:28'),
(26, 28, '[]', '<p><strong data-start=\"177\" data-end=\"281\">Australia is one of the most respected and sought-after study destinations for Bangladeshi students.</strong> With world-class universities, globally recognized qualifications, flexible work opportunities during study, extensive post-study work rights, and strong pathways to future careers, studying in Australia offers remarkable academic and professional growth. <span class=\"\" data-state=\"closed\"><br></span></p><p><span class=\"\" data-state=\"closed\"><br></span>At <span data-start=\"580\" data-end=\"599\">Insaf Immigration</span>, we provide <strong data-start=\"612\" data-end=\"677\">complete support for Australian student visas from Bangladesh</strong>, helping you through each step with clarity, reliability, and a high success rate — from university applications and documentation to visa submission and pre-departure guidance.</p>', '2025-12-16 07:48:38', '2026-01-15 04:25:23'),
(27, 29, '[]', 'Canada consistently ranks among the top countries for international students. Bangladeshi<br>students choose Canada because of:<br>• Globally recognized universities and colleges<br>• Affordable education compared to other English-speaking countries<br>• Strong part-time and post-study work opportunities<br>• Safe, welcoming, and multicultural environment<br>• Clear pathways to permanent residency (PR)<br>• High demand for skilled graduates<br>A Canadian degree opens doors to global career opportunities.', '2026-01-15 02:07:49', '2026-01-15 02:07:49'),
(28, 30, '[]', '<p>Canadian institutions offer career-oriented programs in high-demand fields, including:• Business &amp; Management<br>• Information Technology (IT)<br>• Computer Science &amp; Data Analytics<br>• Engineering<br>• Health Sciences &amp; Nursing<br>• Hospitality &amp; Tourism Management<br>• Accounting &amp; Finance<br>Insaf Immigration helps students select the right course and institution based on academic<br>background, budget, and future career plans.</p>', '2026-01-15 02:08:31', '2026-01-15 02:08:31'),
(29, 31, '[]', '<p>To apply for a Canada Study Permit, students generally need:<br>• Valid passport<br>• Offer letter from a Canadian DLI institution<br>• Academic certificates and transcripts<br>• Proof of funds (bank statement / GIC)<br>• English language proficiency (IELTS or alternatives)<br>• Statement of Purpose (SOP)<br>• Medical and biometric requirements<br>Proper documentation is critical. Our visa experts carefully prepare and review every file to<br>minimize refusal risks.</p>', '2026-01-15 02:09:39', '2026-01-15 02:09:39'),
(30, 32, '[]', '<p>Most Canadian institutions require IELTS, but requirements vary depending on program and institution.<br>Typical requirement:<br>• IELTS overall 6.0 – 6.5<br>Some colleges offer pathway programs or alternative English tests. Our counselors will<br>guide you with the best option for visa success.</p>', '2026-01-15 02:10:32', '2026-01-15 02:10:32'),
(31, 33, '[]', '<p>Canada offers excellent value for money compared to other top destinations.<br>Estimated costs:• Tuition fees: CAD 13,000 – 25,000 per year<br>• Living cost: CAD 10,000 – 15,000 per year<br>At Insaf Immigration, we help students find budget-friendly colleges, scholarships, and cost-effective study options.</p>', '2026-01-15 02:11:28', '2026-01-15 02:11:28'),
(32, 34, '[]', '<p>International students in Canada are allowed to work:<br>• Up to 20 hours per week during study<br>• Full-time during scheduled breaks<br>After graduation, students may apply for a Post-Graduation Work Permit (PGWP), allowing<br>them to gain valuable Canadian work experience and explore PR pathways.</p>', '2026-01-15 02:12:06', '2026-01-15 02:12:06'),
(33, 35, '[]', '<p>Insaf Immigration is a trusted student visa agency in Bangladesh, specializing in Canada.<br>We offer:<br>• Honest and professional counseling<br>• College and university selection support<br>• Strong SOP and visa file preparation<br>• High Canada study visa success rate<br>• Transparent process with no hidden charges<br>• Pre-departure briefing, air ticket, and airport pickup support<br>We focus on long-term success, not short-term promises.</p>', '2026-01-15 02:13:09', '2026-01-15 02:13:09'),
(34, 36, '[]', '<p>If you are planning to study in Canada from Bangladesh, now is the best time to start. With expert guidance and proper planning, your Canadian education dream is within reach.<br>Contact Insaf Immigration today for a free consultation and secure your future in Canada.</p>', '2026-01-15 02:13:51', '2026-01-15 02:13:51'),
(35, 37, '[]', '<p>Europe is becoming one of the most attractive study destinations for Bangladeshi students due to its affordable tuition fees, globally recognized degrees, and wide range of English-taught<br>programs. From modern universities to rich cultural experiences, studying in Europe offers quality education at a reasonable cost.</p><p><br>At Insaf Immigration, we provide complete support for Europe student visas from Bangladesh, helping students choose the right country, university, and visa pathway with confidence.</p>', '2026-01-15 02:14:51', '2026-01-15 02:14:51'),
(36, 38, '[]', '<p>Europe offers excellent academic quality with flexible and budget-friendly options. Bangladeshi students choose Europe because of:<br>• Affordable tuition fees compared to UK, USA, and Australia<br>• English-taught programs across many countries<br>• Globally recognized European degrees<br>• Lower living costs in selected countries<br>• Part-time work opportunities during study<br>• Safe and student-friendly environment<br>European education focuses on both academic excellence and practical skills.</p>', '2026-01-15 02:15:38', '2026-01-15 02:15:38'),
(37, 39, '[]', '<p>Bangladeshi students commonly choose the following European countries:<br>• Germany<br>• Lithuania<br>• Malta<br>• Cyprus<br>• Poland<br>• Hungary<br>• Italy<br>• Latvia<br>Insaf Immigration guides students in selecting the best European country based on budget, academic profile, and visa success rate.</p>', '2026-01-15 02:16:10', '2026-01-15 02:16:10'),
(38, 40, '[]', '<p>European universities offer a wide range of programs in high-demand fields, including:<br>• Business &amp; Management<br>• Information Technology (IT)<br>• Engineering<br>• Hospitality &amp; Tourism Management<br>• Health Sciences<br>• Computer Science &amp; Data Analytics<br>• International Relations<br>We help students choose career-oriented courses with strong future prospects.</p>', '2026-01-15 02:16:46', '2026-01-15 02:16:46'),
(39, 40, '[]', '<p>Student visa requirements vary by country, but generally include:<br>• Valid passport<br>• University offer letter<br>• Academic certificates and transcripts<br>• Proof of financial capability<br>• English language proficiency (IELTS or alternatives)<br>• Accommodation confirmation<br>• Health insurance<br>Our experienced visa team ensures accurate documentation and strong applications for maximum approval chances.</p>', '2026-01-15 02:17:20', '2026-01-15 02:17:20'),
(40, 42, '[]', '<p>Many European countries offer IELTS and non-IELTS options.<br>• Some countries accept MOI (Medium of Instruction)<br>• Some offer foundation or pathway programs<br>Insaf Immigration specializes in non-IELTS and low-IELTS Europe study options, making Europe ideal for Bangladeshi students.</p>', '2026-01-15 02:17:59', '2026-01-15 02:17:59'),
(41, 43, '[]', '<p>One of the biggest advantages of studying in Europe is affordability.<br>Estimated costs:<br>• Tuition fees: EUR 2,500 – 8,000 per year (depending on country &amp; course)<br>• Living cost: EUR 300 – 700 per month<br>We help students find low-cost Europe study programs with high visa success rates.</p>', '2026-01-15 02:18:31', '2026-01-15 02:18:31'),
(42, 44, '[]', '<p>International students in Europe can work part-time during their studies, depending on country regulations.<br>Benefits include:<br>• Earning while studying</p><p>• Supporting living expenses<br>• Gaining international work experience</p><p><br>Some countries also offer post-study stay or job search opportunities.</p>', '2026-01-15 02:19:27', '2026-01-15 02:19:27'),
(43, 45, '[]', '<p>Insaf Immigration is a trusted student visa agency in Bangladesh with strong expertise in Europe.<br>We offer:<br>• Honest and professional counseling<br>• Country-wise university selection<br>• Non-IELTS and budget-friendly options<br>• Strong visa documentation support<br>• High Europe student visa success rate<br>• Transparent process with no hidden charges<br>We guide students with real solutions, not false promises</p>', '2026-01-15 02:20:02', '2026-01-15 02:20:02'),
(44, 46, '[]', '<p>If you are planning to study in Europe from Bangladesh, now is the perfect time to take action. With expert guidance and affordable options, your European education dream is achievable.<br>Contact Insaf Immigration today for a free consultation and begin your journey to Europe.</p>', '2026-01-15 02:20:42', '2026-01-15 02:20:42'),
(45, 47, '[]', '<p>The United States of America is the world’s top destination for higher education, offering unmatched academic quality, global recognition, and career opportunities. With advanced research facilities, flexible course options, and strong post-study work opportunities, studying in the USA provides unlimited possibilities for Bangladeshi students.</p><p><br>At Insaf Immigration, we provide complete support for USA student visas from Bangladesh, ensuring proper guidance, accurate documentation, and strong visa interview preparation.</p>', '2026-01-15 02:21:23', '2026-01-15 02:21:23'),
(46, 48, '[]', '<p>The USA hosts the largest number of international students globally. Bangladeshi students choose the USA because of:<br>• World-renowned universities and colleges<br>• Flexible education system with multiple course options<br>• Globally recognized degrees<br>• Advanced research and innovation facilities<br>• Strong career and employment prospects<br>• Diverse and multicultural student environment</p><p>A US degree significantly increases global career opportunities.</p>', '2026-01-15 02:22:05', '2026-01-15 02:22:05'),
(47, 49, '[]', '<p>US institutions offer a wide range of programs across all academic levels, including:<br>• Business Administration (MBA)<br>• Computer Science &amp; Information Technology<br>• Engineering<br>• Data Science &amp; Artificial Intelligence<br>• Health Sciences<br>• Economics &amp; Finance<br>• Hospitality &amp; Tourism Management<br>Insaf Immigration helps students choose the right university and course based on academic profile, budget, and long-term career goals.</p>', '2026-01-15 02:22:35', '2026-01-15 02:22:35'),
(48, 50, '[]', '<p>To study in the USA, students must apply for an F-1 Student Visa.<br>General requirements include:<br>• Valid passport<br>• I-20 form from a SEVP-approved institution<br>• Academic certificates and transcripts<br>• Proof of financial capability<br>• English language proficiency (IELTS / TOEFL / Duolingo)<br>• Strong Statement of Purpose (SOP)<br>• Visa interview at US Embassy<br>Our experts provide complete visa file preparation and interview coaching, which is crucial for USA visa success.</p>', '2026-01-15 02:23:08', '2026-01-15 02:23:08'),
(49, 51, '[]', '<p>US universities accept multiple English proficiency tests, including:<br>• IELTS<br>• TOEFL<br>• Duolingo English Test<br>Minimum requirements vary by institution, typically:• IELTS 6.0 – 6.5<br>We help students choose the best English test option to maximize admission and visa approval chances.</p>', '2026-01-15 02:23:45', '2026-01-15 02:23:45'),
(50, 52, '[]', '<p>The cost of studying in the USA varies depending on institution and location.<br>Estimated costs:<br>• Tuition fees: USD 15,000 – 40,000 per year<br>• Living cost: USD 10,000 – 18,000 per year<br>At Insaf Immigration, we assist students in finding affordable US universities, scholarships, and effective study pathways.</p>', '2026-01-15 02:24:15', '2026-01-15 02:24:15'),
(51, 53, '[]', '<p>International students in the USA can work through:<br>• On-campus jobs during study<br>• OPT (Optional Practical Training) after graduation<br>• CPT (Curricular Practical Training) during study (if eligible)<br>These opportunities allow students to gain valuable US work experience.</p>', '2026-01-15 02:24:51', '2026-01-15 02:24:51'),
(52, 54, '[]', '<p>Insaf Immigration is a trusted student visa consultancy in Bangladesh, with strong experience in USA applications.<br>We provide:<br>• Honest and professional counseling<br>• University and admission support<br>• Strong SOP and financial documentation<br>• USA visa interview preparation<br>• High USA student visa success rate<br>• Transparent process with no hidden costs<br>We prepare students professionally, strategically, and confidently</p>', '2026-01-15 02:25:23', '2026-01-15 02:25:23'),
(53, 55, '[]', '<p>If you are planning to study in the USA from Bangladesh, expert guidance is essential. With the right preparation and support, your American education dream is achievable.<br>Contact Insaf Immigration today for a free consultation and take your first step toward studying in the USA.</p>', '2026-01-15 02:25:54', '2026-01-15 02:25:54'),
(54, 56, '[]', '<p>Japan is becoming an increasingly popular study destination for Bangladeshi students due to its affordable education system, strong academic standards, advanced technology, and excellent part-time work opportunities. With a safe environment and growing demand for international students, studying in Japan offers both education and career stability.</p><p><br>At Insaf Immigration, we provide complete support for Japan student visas from Bangladesh, guiding students from admission to visa approval with honesty and expertise.</p>', '2026-01-15 02:26:37', '2026-01-15 02:26:37'),
(55, 57, '[]', '<p>Japan offers a unique combination of quality education, affordability, and work opportunities.<br>Bangladeshi students choose Japan because of:<br>• Affordable tuition fees and living costs<br>• High-quality education with global recognition<br>• Strong part-time job opportunities<br>• Safe, disciplined, and student-friendly environment<br>• Advanced technology and innovation-focused education<br>• Long-term job and residence opportunities<br>Japan is ideal for students seeking study + work balance</p>', '2026-01-15 02:27:16', '2026-01-15 02:27:16'),
(56, 58, '[]', '<p>Japanese institutions offer a wide range of programs, especially in:<br>• Information Technology (IT)<br>• Engineering &amp; Technology<br>• Business &amp; Management<br>• Hospitality &amp; Tourism<br>• Japanese Language Programs<br>• Science &amp; Research-based studies<br>Insaf Immigration helps students choose the right institution and program based on academic profile and future career plans.</p>', '2026-01-15 02:27:45', '2026-01-15 02:27:45'),
(57, 59, '[]', '<p>To apply for a Japan student visa, students generally need:<br>• Valid passport<br>• Certificate of Eligibility (COE)<br>• Admission letter from Japanese institution<br>• Academic certificates and transcripts• Proof of financial capability<br>• Japanese language or English proficiency (depending on program)<br>Our experienced visa team ensures accurate documentation and strong applications to increase approval chances.</p>', '2026-01-15 02:28:29', '2026-01-15 02:28:29'),
(58, 60, '[]', '<p>Language requirements depend on the program:<br>• Japanese language programs may require basic Japanese or JLPT<br>• English-taught programs may require IELTS or equivalent</p><p><br>Insaf Immigration provides guidance for both Japanese-taught and English-taught programs,making Japan accessible for Bangladeshi students.</p>', '2026-01-15 02:29:03', '2026-01-15 02:29:03'),
(59, 61, '[]', '<p>Japan offers affordable study options compared to many Western countries.<br>Estimated costs:<br>• Tuition fees: JPY 600,000 – 1,200,000 per year<br>• Living cost: JPY 70,000 – 120,000 per month<br>We help students find budget-friendly institutions and accommodation options.</p>', '2026-01-15 02:29:35', '2026-01-15 02:29:35'),
(60, 62, '[]', '<p>International students in Japan can work:<br>• Up to 28 hours per week during study<br>• Full-time during vacations<br>Part-time jobs help students support living expenses and gain work experience. Many students later secure full-time jobs in Japan.</p>', '2026-01-15 02:30:06', '2026-01-15 02:30:06'),
(61, 63, '[]', '<p>Insaf Immigration is a trusted student visa agency in Bangladesh, with strong experience in Japan.<br>We offer:<br>• Honest and professional counseling• School and program selection support<br>• Strong visa documentation &amp; COE guidance<br>• High Japan student visa success rate<br>• Transparent process with no hidden charges<br>• Pre-departure briefing, air ticket, and airport pickup support<br>We focus on real opportunities, not false promises</p>', '2026-01-15 02:30:45', '2026-01-15 02:30:45'),
(62, 64, '[]', '<p>If you are planning to study in Japan from Bangladesh, now is the right time to start. With proper guidance and affordable options, your Japanese education dream is achievable.<br>Contact Insaf Immigration today for a free consultation and take your first step toward studying in Japan.</p>', '2026-01-15 02:31:20', '2026-01-15 02:31:20'),
(63, 65, '[]', '<p>Malta has become a top choice for Bangladeshi students looking for affordable European education, English-taught programs, and strong student visa success rates. As an English- speaking EU country, studying in Malta offers globally recognized qualifications and real European exposure.<br>At Insaf Immigration, we provide complete support for Malta student visas from Bangladesh, ensuring a smooth process from admission to visa approval and beyond.</p>', '2026-01-15 02:32:58', '2026-01-15 02:32:58'),
(64, 66, '[]', '<p>Malta offers a unique combination of quality education, work opportunities, and student- friendly visa policies. Bangladeshi students prefer Malta because of:<br>• English as the official language<br>• Affordable tuition fees compared to other EU countries<br>• High Malta student visa approval rate<br>• Part-time work opportunities during study<br>• Globally recognized EU qualifications<br>• Safe and welcoming environment<br>• Strong links with European job markets<br>Malta is ideal for students seeking study plus work opportunities in Europe.</p>', '2026-01-15 02:33:29', '2026-01-15 02:33:29'),
(65, 67, '[]', '<p>Malta follows a European education framework aligned with the Malta Qualifications Framework (MQF).<br>Institutions in Malta offer:<br>• Diploma, Advanced Diploma, Bachelor’s, and Master’s programs<br>• Career-oriented and industry-relevant courses<br>• Practical learning with internship opportunities</p><p>Many Maltese institutions maintain international partnerships, ensuring global acceptance of degrees</p>', '2026-01-15 02:34:07', '2026-01-15 02:34:07'),
(66, 68, '[]', '<p>Malta offers high-demand programs for international students, including:<br>• Business Management<br>• Strategic Management &amp; Leadership<br>• Hospitality &amp; Tourism Management<br>• Accounting &amp; Finance<br>• Information Technology (IT)<br>• Digital Marketing<br>• Health &amp; Social Care<br>• Logistics &amp; Supply Chain Management<br>Insaf Immigration assists students in selecting approved Maltese institutions and job-oriented programs.</p>', '2026-01-15 02:34:41', '2026-01-15 02:34:41'),
(67, 69, '[]', '<p>To apply for a Malta student visa, Bangladeshi students typically need:<br>• Valid passport<br>• Offer letter from a recognized Maltese institution<br>• Academic certificates and transcripts<br>• Proof of financial capability<br>• English language proficiency (IELTS or alternatives)<br>• Accommodation confirmation<br>• Health insurance and medical documents<br>Our visa experts prepare strong documentation files, significantly improving approval chances.</p>', '2026-01-15 02:35:15', '2026-01-15 02:35:15'),
(68, 70, '[]', '<p>Malta offers flexible English language requirements.<br>• Many institutions accept MOI (Medium of Instruction)<br>• Some programs allow low IELTS or alternative English proof<br>• English foundation programs are available<br>Insaf Immigration specializes in non-IELTS and low-IELTS Malta study visa options, making Malta accessible for more Bangladeshi students.</p>', '2026-01-15 02:35:54', '2026-01-15 02:35:54'),
(69, 71, '[]', '<p>Malta is considered a budget-friendly EU study destination.<br>Estimated costs:<br>• Tuition fees: EUR 3,500 – 8,000 per year<br>• Living cost: EUR 500 – 800 per month<br>We guide students to affordable institutions and help plan finances realistically.</p>', '2026-01-15 02:36:29', '2026-01-15 02:36:29'),
(70, 72, '[]', '<p>International students in Malta are allowed to work part-time during their studies.<br>Key benefits:<br>• Legal part-time work opportunities<br>• Monthly income to support living expenses<br>• Valuable European work experience<br>• Better employability after graduation<br>Many students find work in hospitality, retail, and service sectors.</p>', '2026-01-15 02:37:10', '2026-01-15 02:37:10'),
(71, 73, '[]', '<p>Malta offers a vibrant, safe, and multicultural environment.<br>• English-speaking society<br>• Warm Mediterranean climate<br>• Student-friendly lifestyle<br>• Multinational communities<br>• Easy access to other European countries<br>Bangladeshi students feel comfortable adapting to life in Malta.</p>', '2026-01-15 02:38:05', '2026-01-15 02:38:05'),
(72, 74, '[]', '<p>Insaf Immigration is a leading student visa consultancy in Bangladesh, with proven success inMalta.<br>We provide:<br></p><p>• Honest and professional counseling<br>• Approved institution and course selection<br>• Non-IELTS and study plus work options<br>• Strong visa file preparation<br>• High Malta visa success rate<br>• Transparent process with no hidden charges<br>• Pre-departure support, air ticket &amp; airport pickup assistance</p><p><br>We focus on real results, not fake promises.</p>', '2026-01-15 02:39:28', '2026-01-15 02:39:28'),
(73, 75, '[]', '<p>If you are planning to study in Malta from Bangladesh, this is the perfect time to apply. With English-taught education, EU recognition, and strong work opportunities, Malta is an excellent choice.<br>Contact Insaf Immigration today for a free consultation and secure your future in Europe.</p>', '2026-01-15 02:40:24', '2026-01-15 02:40:24'),
(74, 76, '[]', '<p>Malaysia has become a top destination for Bangladeshi students who want internationally recognized education at a low cost with a smooth and fast student visa process. With English- taught programs, modern universities, and excellent work opportunities, studying in Malaysia offers real value for money.<br>At Insaf Immigration, we provide complete and professional support for Malaysia student visas from Bangladesh, from admission to visa approval and pre-departure assistance.</p>', '2026-01-15 02:41:02', '2026-01-15 02:41:02'),
(75, 77, '[]', '<p>Malaysia offers a perfect balance of affordability, quality education, and career opportunities.<br>Bangladeshi students choose Malaysia because of:<br>• Low tuition fees and living costs<br>• English-taught Diploma, Bachelor’s, and Master’s programs<br>• High Malaysia student visa approval rate<br>• Fast and student-friendly visa process<br>• Study plus part-time work opportunities<br>• International campuses and modern facilities<br>• Globally recognized qualifications<br>Malaysia is ideal for students seeking quality education with budget control</p>', '2026-01-15 02:41:38', '2026-01-15 02:41:38'),
(76, 78, '[]', '<p>Malaysia follows a globally recognized education framework and hosts top private and international universities.<br>Institutions in Malaysia offer:<br>• Diploma, Bachelor’s, and Master’s programs• UK, Australian, and international university affiliations<br>• Industry-focused and practical learning<br>• Credit transfer and pathway programs<br>Many Malaysian universities have branch campuses of UK and Australian institutions, ensuring global acceptance.</p>', '2026-01-15 02:42:31', '2026-01-15 02:42:31'),
(77, 79, '[]', '<p>Malaysia offers a wide range of in-demand programs, including:<br>• Business Administration &amp; Management<br>• Accounting &amp; Finance<br>• Hospitality &amp; Tourism Management<br>• Information Technology (IT)<br>• Computer Science<br>• Engineering<br>• Digital Marketing<br>• Health &amp; Nursing Programs<br>Insaf Immigration helps students choose approved universities and career-oriented courses based on academic background and budget.</p>', '2026-01-15 02:43:27', '2026-01-15 02:43:27'),
(78, 80, '[]', '<p>To apply for a Malaysia student visa, Bangladeshi students generally need:<br>• Valid passport<br>• Offer letter from a recognized Malaysian institution<br>• Academic certificates and transcripts<br>• Proof of financial capability<br>• English language proficiency (IELTS or alternatives)<br>• Medical and health screening reports<br>Our experienced visa team prepares strong, errorfree applications to ensure high visa success.</p>', '2026-01-15 02:43:59', '2026-01-15 02:43:59'),
(79, 81, '[]', '<p>Malaysia offers flexible English language requirements.<br>• Many universities accept MOI (Medium of Instruction)<br>• Low IELTS scores may be accepted<br>• English foundation programs available<br>• Some programs allow study without IELTS</p><p>Insaf Immigration specializes in non-IELTS and low-IELTS Malaysia study visa options for Bangladeshi students.</p>', '2026-01-15 02:44:37', '2026-01-15 02:44:37'),
(80, 82, '[]', '<p>Malaysia is one of the most affordable study destinations in Asia.<br>Estimated costs:<br>• Tuition fees: BDT 3.5 – 6 lakh per year (approx.)<br>• Living cost: BDT 30,000 – 45,000 per month<br>We guide students to budget-friendly institutions with transparent fee structures.</p>', '2026-01-15 02:45:17', '2026-01-15 02:45:17'),
(81, 83, '[]', '<p>International students in Malaysia are allowed to work part-time during semester breaks and holidays.<br>Benefits include:<br>• Supporting personal expenses<br>• Gaining international work experience<br>• Exposure to multinational work environments<br>Many Bangladeshi students work in hospitality, retail, and service sectors.</p>', '2026-01-15 02:45:54', '2026-01-15 02:45:54'),
(82, 84, '[]', '<p>Malaysia is one of the most comfortable countries for Bangladeshi students.<br>• Muslim-friendly environment<br>• Affordable halal food<br>• Large Bangladeshi student community<br>• Safe cities and modern lifestyle<br>• Easy cultural adaptation<br>Malaysia offers a smooth transition for first-time international students.</p>', '2026-01-15 02:46:27', '2026-01-15 02:46:27'),
(83, 85, '[]', '<p>Insaf Immigration is a trusted and result-driven student visa agency in Bangladesh, with strong success in Malaysia.</p><p>We provide:<br>• Honest and professional counseling<br>• Approved university and course selection<br>• Non-IELTS and work-based study options<br>• Strong visa file preparation<br>• High Malaysia visa success rate<br>• Transparent process with no hidden charges<br>• Air ticket support and airport pickup assistance<br>We focus on real approvals, not fake guarantees</p>', '2026-01-15 02:47:07', '2026-01-15 02:47:07'),
(84, 86, '[]', '<p>If you are planning to study in Malaysia from Bangladesh, now is the best time to apply. With affordable education, fast visa processing, and international recognition, Malaysia is a smart choice.<br>Contact Insaf Immigration today for a free consultation and secure your future abroad.</p>', '2026-01-15 02:47:46', '2026-01-15 02:47:46'),
(85, 87, '[]', '<p>Russia is one of the most affordable and high-demand study destinations for Bangladeshi students seeking quality education, easy visa processing, and globally recognized degrees. With world-ranked universities, low tuition fees, and simple admission requirements, studying in Russia has become a top choice for Bangladeshi students every year.<br>Insaf Immigration is a trusted and experienced Russia student visa consultant in Bangladesh, providing complete guidance from university admission to visa approval and departure support.</p>', '2026-01-15 02:48:33', '2026-01-15 02:48:33'),
(86, 88, '[]', '<p>Russia offers a unique combination of quality education, low cost, and high visa success rate, making it extremely popular among Bangladeshi students.<br>Key reasons to choose Russia:<br>• Low tuition fees compared to Europe, UK, and Australia<br>• High Russia student visa approval rate for Bangladeshi students<br>• Globally recognized medical, engineering, and science degrees<br>• Simple and fast visa processing<br>• No IELTS required for many programs<br>• Low living cost<br>• Government-approved universities<br>• Safe and student-friendly campuses<br>Russia is especially ideal for students looking for budget-friendly study abroad options</p>', '2026-01-15 02:49:43', '2026-01-15 02:49:43'),
(87, 89, '[]', '<p>Russia has one of the strongest education systems in the world, especially in:<br>• Medicine (MBBS)<br>• Engineering<br>• Science &amp; Technology<br>• Business and Management<br>Russian universities are government-recognized and follow international academic standards. Degrees obtained in Russia are recognized in Bangladesh and worldwide.<br>Programs are offered in:<br>• English Medium<br>• Russian Medium (with language preparation year)</p>', '2026-01-15 02:50:14', '2026-01-15 02:50:14'),
(88, 90, '[]', '<p>Russia is globally famous for its high-quality and affordable programs. Most popular courses among Bangladeshi students include:<br>• MBBS / General Medicine<br>• Engineering (Mechanical, Electrical, Civil)<br>• Computer Science &amp; IT<br>• Business Administration<br>• Economics<br>• International Relations<br>• Aviation &amp; Aerospace<br>• Architecture<br>Insaf Immigration helps students select MOE-approved and high-ranking Russian universities.</p>', '2026-01-15 02:50:57', '2026-01-15 02:50:57'),
(89, 91, '[]', '<p>Russia is one of the top destinations for MBBS abroad.</p><p>Benefits of MBBS in Russia:<br>• Affordable tuition fees<br>• English-medium instruction<br>• No donation or capitation fee<br>• WHO &amp; NMC-recognized universities<br>• High-quality clinical training<br>• Safe campuses and hostels<br>Insaf Immigration is highly experienced in MBBS admission and Russia medical student visa processing.</p>', '2026-01-15 02:51:32', '2026-01-15 02:51:32'),
(90, 92, '[]', '<p>To apply for a Russia student visa from Bangladesh, students generally need:<br>• Valid passport<br>• Offer letter from a Russian university<br>• Academic certificates and transcripts<br>• Medical reports (including HIV test)<br>• Visa invitation letter<br>• Passport-size photographs</p><p>Russia has one of the simplest student visa processes, and our team ensures 100% accurate documentation.</p>', '2026-01-15 02:52:11', '2026-01-15 02:52:11'),
(91, 93, '[]', '<p>One of the biggest advantages of Russia is:<br>No IELTS required for most programs</p><p><br>• Many universities accept students without IELTS<br>• English-medium programs available<br>• Language preparation year available if needed</p><p><br>Insaf Immigration specializes in non-IELTS Russia study visa options, making Russia ideal for Bangladeshi students.</p>', '2026-01-15 02:53:07', '2026-01-15 02:53:07'),
(92, 94, '[]', '<p>Russia is one of the lowest-cost study destinations in the world.<br>Estimated costs:<br>• Tuition fees: USD 2,500 – 5,000 per year<br>• Living cost: USD 150 – 300 per month<br>This makes Russia perfect for students from middle-income families in Bangladesh</p>', '2026-01-15 02:53:42', '2026-01-15 02:53:42'),
(93, 95, '[]', '<p>International students in Russia can work part-time under certain conditions.<br>Benefits:<br>• Support living expenses<br>• Gain international exposure<br>• Develop practical skills<br>Although study is the main focus, part-time work helps students manage daily costs.</p>', '2026-01-15 02:54:14', '2026-01-15 02:54:14'),
(94, 96, '[]', '<p>Russia hosts thousands of Bangladeshi students every year.<br></p><p><br>Student life benefits:</p><p>• Affordable accommodation<br>• University hostels<br>• Multicultural environment<br>• Strong Bangladeshi student communities<br>• Safe cities and campuses</p><p><br>Students receive full orientation and support upon arrival.</p>', '2026-01-15 02:55:13', '2026-01-15 02:55:13'),
(95, 97, '[]', '<p>Insaf Immigration is a leading Russia student visa agency in Bangladesh with a strong track record.<br></p><p><br>We provide:<br>• Honest and expert counseling<br>• Government-approved university admission<br>• Non-IELTS study options<br>• Strong visa documentation preparation<br>• High Russia student visa success rate<br>• Transparent pricing with no hidden charges<br>• Air ticket support &amp; airport pickup</p><p><br>We focus on real approvals, not false promises.</p>', '2026-01-15 02:55:49', '2026-01-15 02:55:49'),
(96, 98, '[]', '<p>If you are planning to study in Russia from Bangladesh, now is the right time to apply. With low cost, easy visa, and world-class education, Russia offers unmatched value.<br>Contact Insaf Immigration today for a free consultation and secure your admission and visa with confidence.</p>', '2026-01-15 02:56:32', '2026-01-15 02:56:32'),
(97, 99, '[]', '<p>Lithuania is emerging as one of the most attractive European study destinations for Bangladeshi students due to its affordable tuition fees, English-taught programs, and strong student visa success rate. As a member of the European Union, studying in Lithuania offers globally recognized education and access to Europe.</p><p><br>At Insaf Immigration, we provide complete support for Lithuania student visas from Bangladesh, guiding students from admission to visa approval with transparency and expertise.</p>', '2026-01-15 02:57:53', '2026-01-15 02:57:53'),
(98, 100, '[]', '<p>Lithuania offers high-quality European education at a reasonable cost. </p><p>Bangladeshi students choose Lithuania because of:<br>• Affordable tuition fees compared to other EU countries<br>• English-taught Bachelor’s and Master’s programs<br>• Simple and student-friendly visa process<br>• Low living costs<br>• EU-recognized degrees<br>• Safe and peaceful environment</p><p><br>Lithuania is ideal for students seeking low-cost study in Europe.</p>', '2026-01-15 02:58:32', '2026-01-15 02:58:32'),
(99, 101, '[]', '<p>Lithuanian universities offer career-focused programs in:<br>• Business &amp; Management<br>• Information Technology (IT)<br>• Engineering<br>• Data Science<br>• International Relations<br>• Logistics &amp; Supply Chain Management<br>• Health Sciences</p><p><br>Insaf Immigration helps students choose approved universities and in-demand courses with strong visa approval history.</p>', '2026-01-15 02:59:09', '2026-01-15 02:59:09'),
(100, 102, '[]', '<p>To apply for a Lithuania student visa, students generally need:<br>• Valid passport<br>• Offer letter from a Lithuanian institution<br>• Academic certificates and transcripts<br>• Proof of financial capability<br>• English language proficiency (IELTS or alternatives)<br>• Accommodation confirmation<br>• Health insurance</p><p><br>Our visa experts ensure complete and accurate documentation to maximize approval chances.</p>', '2026-01-15 02:59:40', '2026-01-15 02:59:40'),
(101, 103, '[]', '<p>Lithuania offers IELTS and non-IELTS study options.<br>• Some universities accept MOI (Medium of Instruction)<br>• Alternative English tests may be accepted<br></p><p><br>Insaf Immigration specializes in non-IELTS Lithuania study visa options, making Lithuaniaaccessible for Bangladeshi students.</p>', '2026-01-15 03:00:22', '2026-01-15 03:00:22'),
(102, 104, '[]', '<p>Lithuania is one of the most affordable EU study destinations.<br>Estimated costs:<br>• Tuition fees: EUR 2,500 – 5,000 per year<br>• Living cost: EUR 300&nbsp; 600 per month</p><p><br>We guide students toward budget-friendly Lithuanian universities with genuine study programs.</p>', '2026-01-15 03:01:14', '2026-01-15 03:01:14'),
(103, 105, '[]', '<p>International students in Lithuania are allowed to work part-time during study.</p><p><br>Benefits include:<br>• Supporting living expenses<br>• Gaining European work experience<br>• Enhancing employability after graduation</p><p><br>Some students also explore poststudy work opportunities within the EU.</p>', '2026-01-15 03:02:01', '2026-01-15 03:02:01'),
(104, 106, '[]', '<p>Insaf Immigration is a trusted student visa agency in Bangladesh, with strong experience in Lithuania.</p><p><br>We offer:<br>• Honest and professional counseling<br>• University and course selection support<br>• Non-IELTS and affordable study options<br>• Strong visa documentation preparation<br>• High Lithuania student visa success rate<br>• Transparent process with no hidden charges</p><p><br>We deliver real European education opportunities, not false promises.</p>', '2026-01-15 03:02:36', '2026-01-15 03:02:36'),
(105, 107, '[]', '<p>If you are planning to study in Lithuania from Bangladesh, now is the right time to apply. With affordable education and EU exposure, Lithuania is an excellent choice.<br>Contact Insaf Immigration today for a free consultation and begin your European journey.</p>', '2026-01-15 03:03:11', '2026-01-15 03:03:11'),
(106, 108, '[]', '<p>Cyprus has emerged as one of the most attractive European study destinations for Bangladeshi students seeking affordable education, high visa success rates, and internationally recognized degrees. As an English-speaking education hub in Europe, studying in Cyprus provides quality education with a smooth student visa process.</p><p><br>At Insaf Immigration, we provide complete and professional support for Cyprus student visas from Bangladesh, from university selection to visa approval and pre-departure guidance.</p>', '2026-01-15 03:04:02', '2026-01-15 03:04:02'),
(107, 109, '[]', '<p>Cyprus offers a perfect balance of quality education, affordability, and European exposure. Bangladeshi students increasingly choose Cyprus because of:<br>• Affordable tuition fees compared to other EU countries<br>• English-taught Bachelor’s and Master’s programs<br>• High student visa approval rate for Bangladeshi students<br>• Low living costs<br>• Safe, peaceful, and student-friendly environment<br>• European-standard education system<br>• Recognized degrees accepted across Europe and beyond</p><p><br>Cyprus is especially popular for students looking for low-cost European study options with reliable visa outcomes</p>', '2026-01-15 03:04:52', '2026-01-15 03:04:52'),
(108, 110, '[]', '<p>Cyprus follows a European education framework with strong academic standards.&nbsp;<br><br>Universities offer:<br>• Diploma, Bachelor’s, and Master’s programs<br>• Practical and career-oriented courses<br>• International faculty and modern campuses<br><br>Many universities maintain partnerships with UK and European institutions, ensuring global recognition of qualifications.</p>', '2026-01-15 03:05:34', '2026-01-15 03:05:34'),
(109, 111, '[]', '<p>Cyprus universities offer a wide range of programs in high-demand fields, including:<br><br>• Business Administration &amp; Management<br>• Accounting &amp; Finance<br>• Hospitality &amp; Tourism Management<br>• Information Technology (IT)<br>• Computer Science<br>• International Relations<br>• Health Sciences<br>• Maritime Studies<br><br>Insaf Immigration helps students select approved universities and career-focused programs based on academic profile and budget.</p>', '2026-01-15 03:06:16', '2026-01-15 03:06:16'),
(110, 112, '[]', '<p>To apply for a Cyprus student visa, Bangladeshi students generally need:<br><br>• Valid passport<br>• Offer letter from a recognized Cyprus university<br>• Academic certificates and transcripts<br>• Proof of financial capability<br>• English language proficiency (IELTS or alternative)<br>• Accommodation confirmation<br>• Health insurance and medical reports<br><br>Our experienced visa team ensures complete, accurate, and well-organized documentation, significantly increasing visa approval chances.</p>', '2026-01-15 03:06:55', '2026-01-15 03:06:55'),
(111, 113, '[]', '<p>Cyprus offers flexible English language requirements.<br><br>• Many universities accept MOI (Medium of Instruction)<br>• Some institutions allow low IELTS or alternative English tests<br>• English foundation programs are also available<br><br>Insaf Immigration specializes in non-IELTS and low-IELTS Cyprus study visa options, making Cyprus accessible to a wider range of Bangladeshi students.</p>', '2026-01-15 03:07:28', '2026-01-15 03:07:28');
INSERT INTO `destination_item_sections` (`id`, `destination_item_id`, `images`, `description`, `created_at`, `updated_at`) VALUES
(112, 114, '[]', '<p>Cyprus is among the most affordable European study destinations.<br><br>Estimated costs:<br>• Tuition fees: EUR 3,000 – 7,000 per year<br>• Living cost: EUR 400 – 700 per month<br><br>We guide students toward budget-friendly Cyprus universities and assist with cost planning.</p>', '2026-01-15 03:08:36', '2026-01-15 03:08:36'),
(113, 115, '[]', '<p>International students in Cyprus are allowed to work part-time during their studies, subject to regulations.<br><br>Benefits include:<br>• Supporting living expenses<br>• Gaining European work experience<br>• Improving employability after graduation<br><br>Some students also explore post-study employment opportunities in Cyprus or other European countries.</p>', '2026-01-15 03:09:14', '2026-01-15 03:09:14'),
(114, 116, '[]', '<p>Cyprus offers a welcoming and multicultural environment for international students.<br><br>• Safe cities and low crime rate<br>• Warm climate and Mediterranean lifestyle<br>• Affordable accommodation options<br>• Friendly local communities<br><br>Bangladeshi students find Cyprus comfortable and supportive for both study and living.</p>', '2026-01-15 03:09:47', '2026-01-15 03:09:47'),
(115, 117, '[]', '<p>Insaf Immigration is a trusted student visa agency in Bangladesh, with strong expertise in Cyprus.<br><br>We provide:<br>• Honest and professional counseling<br>• University and course selection support<br>• Non-IELTS and affordable Europe options<br>• Strong visa documentation preparation<br>• High Cyprus student visa success rate<br>• Transparent process with no hidden charges<br>• Pre-departure briefing, air ticket, and airport pickup support<br><br>We focus on long-term student success, not short-term sales</p>', '2026-01-15 03:10:26', '2026-01-15 03:10:26'),
(116, 118, '[]', '<p>If you are planning to study in Cyprus from Bangladesh, now is the right time to apply. With affordable education, European recognition, and expert guidance, Cyprus offers an excellent pathway to global opportunities.<br><br>Contact Insaf Immigration today for a free consultation and take your first step toward studying in Europe.</p>', '2026-01-15 03:11:24', '2026-01-15 03:11:24'),
(117, 119, '[]', '<p>South Korea has emerged as one of the most popular destinations for Bangladeshi students seeking high-quality education, advanced research opportunities, and global career exposure. With world-ranked universities, affordable tuition options, and generous scholarships, studying in South Korea offers an excellent return on investment.<br><br>Insaf Immigration is a trusted South Korea student visa consultant in Bangladesh, providing complete support from university admission to visa approval and pre-departure guidance.</p>', '2026-01-15 03:34:37', '2026-01-15 03:34:37'),
(118, 120, '[]', '<p>South Korea offers a powerful combination of academic excellence, innovation, and global recognition.<br><br>Key reasons Bangladeshi students choose South Korea:<br>• World-ranked universities and research institutions<br>• High-quality education in science, technology, and business<br>• Affordable tuition fees compared to other developed countries<br>• Wide range of scholarships for international students<br>• English-taught Bachelor’s and Master’s programs<br>• Safe, modern, and student-friendly environment<br>• Strong global job prospects after graduation<br><br>South Korea is ideal for students aiming for top-tier education with global exposure.</p>', '2026-01-15 03:35:25', '2026-01-15 03:35:25'),
(119, 121, '[]', '<p>South Korea’s education system is globally recognized for its academic rigor and innovation.<br><br>Universities offer:<br>• Bachelor’s, Master’s, and PhD programs<br>• English-taught and Korean-taught programs<br>• Research-based and industry-linked education<br>• Strong collaboration with global companies<br><br>Degrees from South Korea are internationally recognized and highly valued by employers worldwide.</p>', '2026-01-15 03:36:08', '2026-01-15 03:36:08'),
(120, 122, '[]', '<p>South Korean universities offer a wide range of high-demand programs, including:<br><br>• Engineering (Electrical, Mechanical, Civil, Electronics)<br>• Computer Science &amp; Information Technology<br>• Artificial Intelligence &amp; Data Science<br>• Business Administration &amp; Management<br>• International Business<br>• Biotechnology<br>• Media &amp; Communication<br>• Korean Language &amp; Cultural Studies<br><br>Insaf Immigration helps students choose top-ranked and government-approved Korean universities based on academic profile and career goals.</p>', '2026-01-15 03:37:54', '2026-01-15 03:37:54'),
(121, 123, '[]', '<p>To apply for a South Korea student visa from Bangladesh, students typically need:<br><br>• Valid passport<br>• Offer letter from a South Korean university<br>• Academic certificates and transcripts<br>• Proof of financial capability<br>• English or Korean language proficiency documents<br>• Medical and health reports<br>Our expert team ensures accurate and complete visa documentation, significantly improving approval success.</p>', '2026-01-15 03:38:30', '2026-01-15 03:38:30'),
(122, 124, '[]', '<p>South Korea offers flexible language requirements.<br><br>• Many universities offer English-taught programs (IELTS accepted)<br>• Some programs accept MOI (Medium of Instruction)<br>• Korean-taught programs require TOPIK<br>• Korean language foundation programs available<br><br>Insaf Immigration guides students for both English and Korean language pathways, including language preparation options.</p>', '2026-01-15 03:39:12', '2026-01-15 03:39:12'),
(123, 125, '[]', '<p>South Korea offers high-quality education at a reasonable cost.<br><br>Estimated costs:<br>• Tuition fees: USD 3,000 – 7,000 per year<br>• Living cost: USD 400 – 800 per month<br><br>Scholarships and part-time work opportunities help reduce expenses.</p>', '2026-01-15 03:40:01', '2026-01-15 03:40:01'),
(124, 126, '[]', '<p>International students in South Korea are allowed to work part-time during their studies.<br><br>Benefits include:<br>• Legal part-time work opportunities<br>• Monthly income to support living expenses<br>• Exposure to advanced work culture<br>• Better employability after graduation<br><br>Popular student jobs include café work, research assistant roles, and teaching support.</p>', '2026-01-15 03:40:36', '2026-01-15 03:40:36'),
(125, 127, '[]', '<p>South Korea offers a safe, modern, and exciting lifestyle.<br><br>• Advanced public transportation<br>• High safety standards<br>• Modern cities and vibrant student life<br>• Multicultural campuses<br>• Strong international student support systems<br><br>Bangladeshi students enjoy a supportive and welcoming environment.</p>', '2026-01-15 03:41:14', '2026-01-15 03:41:14'),
(126, 128, '[]', '<p>Insaf Immigration is a reliable and experienced South Korea student visa agency in Bangladesh.<br><br>We provide:<br>• Professional career-based counseling<br>• University and course selection support<br>• Scholarship guidance<br>• Strong visa documentation preparation<br>• High South Korea student visa success rate<br>• Transparent process with no hidden charges<br>• Pre-departure briefing, air ticket &amp; airport pickup assistance<br><br>We guide students with honesty, strategy, and proven results.</p>', '2026-01-15 03:42:00', '2026-01-15 03:42:00'),
(127, 129, '[]', '<p>If you are planning to study in South Korea from Bangladesh, now is the perfect time to apply. With advanced education, scholarships, and global career prospects, South Korea is a powerful study destination.<br>Contact Insaf Immigration today for a free consultation and take your first step toward a world-class education.</p>', '2026-01-15 03:42:48', '2026-01-15 03:42:48');

