INSERT INTO `faqs` (`id`, `question`, `answer`, `created_at`, `updated_at`) VALUES
(3, 'Which countries can I apply to through Insaf Immigration?', 'We provide study visa support for over 15 countries, including Australia, UK, USA, Canada, Malta, Malaysia, Russia, South Korea, Cyprus, Lithuania, New Zealand, Kyrgyzstan, and more. Our team guides you at every step to make your dream of studying abroad a reality.', '2025-12-22 05:48:58', '2026-01-15 04:23:04'),
(4, 'Do I need IELTS or other English language tests to apply?', 'Not necessarily. Some programs in Malaysia, Russia, and Malta do not require IELTS. Our experts will advise you based on your chosen course and country to make your application smooth and hassle-free.', '2026-01-15 04:23:26', '2026-01-15 04:23:40'),
(5, 'Do you charge for file opening or application?', 'We do not charge any kind of application or visa processing fees for the universities and colleges under our portal. Our services for our students are completely free.', '2026-01-15 04:23:56', '2026-01-15 04:23:56');

