(2, 2, 'Health Insurance', '2025-12-18 00:21:02', '2026-01-15 06:30:20'),
(3, 2, 'Why Health Insurance is a Must for Students Abroad', '2026-01-15 06:32:57', '2026-01-15 06:32:57'),
(4, 2, 'Our Health Insurance Services for International Students', '2026-01-15 06:34:11', '2026-01-15 06:34:11'),
(5, 2, 'Why Choosing Insaf Immigration is the Smart Choice', '2026-01-15 06:36:12', '2026-01-15 06:36:12'),
(6, 2, 'Health Insurance Requirements in Popular Study Destinations', '2026-01-15 06:37:44', '2026-01-15 06:37:44'),
(7, 2, 'Why Health Insurance is Crucial for Students', '2026-01-15 06:38:34', '2026-01-15 06:38:34');

