(2, 2, 'Visa Service', '2025-12-18 00:30:34', '2026-01-18 04:57:48'),
(3, 2, 'What Is Our Student Visa Service?', '2026-01-18 04:31:37', '2026-01-18 04:31:37'),
(4, 2, 'Our Visa Services Include', '2026-01-18 04:32:35', '2026-01-18 04:32:35'),
(5, 2, 'Complete Visa Documentation Support', '2026-01-18 04:33:33', '2026-01-18 04:33:33'),
(6, 2, 'SOP Writing & Visa Interview Preparation', '2026-01-18 04:34:50', '2026-01-18 04:34:50'),
(7, 2, 'Embassy & VFS Application Guidance', '2026-01-18 04:35:31', '2026-01-18 04:35:31'),
(8, 2, 'Countries We Provide Student Visa Services For', '2026-01-18 04:37:08', '2026-01-18 04:37:08'),
(9, 2, 'Visa Eligibility Assessment', '2026-01-18 04:50:03', '2026-01-18 04:50:03'),
(11, 2, 'Who Can Apply Through Our Visa Service?', '2026-01-18 04:53:17', '2026-01-18 04:53:17'),
(12, 2, 'Why Professional Visa Service Is Important', '2026-01-18 04:53:54', '2026-01-18 04:53:54'),
(13, 2, 'Why Choose Insaf Immigration for Visa Services?', '2026-01-18 04:54:57', '2026-01-18 04:54:57'),
(14, 2, 'Admission + Visa Success Strategy', '2026-01-18 04:55:38', '2026-01-18 04:55:38'),
(15, 2, 'Start Your Visa Process with Insaf Immigration', '2026-01-18 04:56:13', '2026-01-18 04:56:13');

