CREATE TABLE `visa_item_sections` (
  `id` bigint UNSIGNED NOT NULL,
  `visa_item_id` bigint UNSIGNED NOT NULL,
  `images` json DEFAULT NULL,
  `description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
